// Consolidate all read rows from Google Sheets into a single array
const items = $input.all();
const boardsFromSheet = [];

for (const item of items) {
  const row = item.json || {};
  if (row.BoardName || row.board_name || row.BoardID || row.board_id) {
    boardsFromSheet.push(row);
  }
}

return [{
  json: {
    boardsFromSheet: boardsFromSheet,
    fetchedBoardsCount: boardsFromSheet.length,
    timestamp: new Date().toISOString()
  }
}];

// VALIDATE BRIEF & PREPARE AUDIT DATA FOR ALL 8 VIRAL STYLES (FINMATRIX QUANTITATIVE FALLBACKS)
const prev = $('Pick Next Finmatrix Keyword, Angle & Board').item.json || {};
const rawGemini = $json.candidates?.[0]?.content?.parts?.[0]?.text || '';
const pinStyle = prev.pinStyle || 'STYLE_1_6CARD_GRID';
const kw = prev.targetKeyword || 'Personal Finance Calculator';

const finFallbacks = {
